      },
      "apparatus": {
        "name": "spgpe_simulator",
        "description": "Stochastic projected Gross-Pitaevskii equation simulation in 2D periodic box."
      },
      "background": "The time for the condensate to reach equilibrium after crossing the critical point follows a power law with quench time, with an additional linear term.",
      "initial_observations": [
        "For τ_Q=10, t_eq is around 12.",
        "For τ_Q=100, t_eq is around 40.",
        "For τ_Q=1000, t_eq is around 120."
      ],
      "controls": [
        {
          "name": "tau_q",
          "description": "Quench duration",
          "unit": "dimensionless",
          "minimum": 10,
          "maximum": 1000
        }
      ],
      "readouts": [
        {
          "name": "t_eq",
          "description": "Equilibration time",
          "unit": "dimensionless",
          "resolution": 0.1
        }
      ],
      "oracle": {
        "kind": "closed_form",
        "outputs": {
          "t_eq": {
            "op": "add",
            "args": [
              {
                "op": "multiply",
                "args": [
                  {"param": "amplitude"},
                  {"op": "power", "args": [{"var": "tau_q"}, {"param": "exponent"}]}
                ]
              },
              {
                "op": "multiply",
                "args": [
                  {"param": "linear_coeff"},
                  {"var": "tau_q"}
                ]
              }
            ]
          }
        },
        "paper_parameters": {
          "amplitude": 3.779,
          "exponent": 0.541,
          "linear_coeff": 0.078
        },
        "counterfactual_parameters": {
          "amplitude": 3.779,
          "exponent": 0.5,
          "linear_coeff": 0.078
        }
      },
      "diagnostic_conditions": [
        {"tau_q": 10},
        {"tau_q": 100},
        {"tau_q": 1000}
      ],
      "hidden_conditions": [
        {"tau_q": 30},
        {"tau_q": 300}
      ],
      "budget": 10,
      "max_replicates": 3,
      "confidence_threshold": 0.95,
      "relative_tolerance": 0.1,
      "notes": [
        "The exponent is close to the theoretical KZ prediction of 1/2.",
        "The linear term is small but included in the fit."
      ],
      "counterfactual_change": "Changed the exponent from 0.541 to 0.5, the theoretical KZ value."
    },
    {
